export function validateRunStartedEvent(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "sequence")) fail(contract, `${path}.sequence`, "missing required property");
  if (!Object.hasOwn(record, "fleet_run_id")) fail(contract, `${path}.fleet_run_id`, "missing required property");
  if (!Object.hasOwn(record, "event_type")) fail(contract, `${path}.event_type`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "event_type": {
          if (item !== "RUN_STARTED") fail(contract, `${path}.event_type`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.event_type`, "expected string");
          break;
        }
        case "fleet_run_id": {
          if (typeof item !== "string") fail(contract, `${path}.fleet_run_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.fleet_run_id`, "must contain at least 1 characters");
          break;
        }
        case "generated_at": {
          if (typeof item !== "string") fail(contract, `${path}.generated_at`, "expected string");
          if (Number.isNaN(Date.parse(item as string))) fail(contract, `${path}.generated_at`, "expected date-time string");
          break;
        }
        case "sequence": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.sequence`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.sequence`, "expected integer");
          if ((item as number) < 1.0) fail(contract, `${path}.sequence`, "must be >= 1.0");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateRunningFleetRun(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "fleet_run_id")) fail(contract, `${path}.fleet_run_id`, "missing required property");
  if (!Object.hasOwn(record, "capability")) fail(contract, `${path}.capability`, "missing required property");
  if (!Object.hasOwn(record, "repository_scope")) fail(contract, `${path}.repository_scope`, "missing required property");
  if (!Object.hasOwn(record, "targets")) fail(contract, `${path}.targets`, "missing required property");
  if (!Object.hasOwn(record, "accepted_at")) fail(contract, `${path}.accepted_at`, "missing required property");
  if (!Object.hasOwn(record, "progress")) fail(contract, `${path}.progress`, "missing required property");
  if (!Object.hasOwn(record, "status")) fail(contract, `${path}.status`, "missing required property");
  if (!Object.hasOwn(record, "started_at")) fail(contract, `${path}.started_at`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "accepted_at": {
          if (typeof item !== "string") fail(contract, `${path}.accepted_at`, "expected string");
          if (Number.isNaN(Date.parse(item as string))) fail(contract, `${path}.accepted_at`, "expected date-time string");
          break;
        }
        case "capability": {
          validateReference("CapabilitySnapshot", validateCapabilitySnapshot, item, `${path}.capability`, contract, refStack);
          break;
        }
        case "fleet_run_id": {
          if (typeof item !== "string") fail(contract, `${path}.fleet_run_id`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.fleet_run_id`, "must contain at least 1 characters");
          break;
        }
        case "progress": {
          validateReference("FleetRunProgress", validateFleetRunProgress, item, `${path}.progress`, contract, refStack);
          break;
        }
        case "repository_scope": {
          validateUnion(contract, `${path}.repository_scope`, [
            () => {
              validateReference("AllRepositoryScope", validateAllRepositoryScope, item, `${path}.repository_scope`, contract, refStack);
            },
            () => {
              validateReference("ExplicitRepositoryScope", validateExplicitRepositoryScope, item, `${path}.repository_scope`, contract, refStack);
            },
          ]);
          break;
        }
        case "source": {
          validateReference("FleetRunSource", validateFleetRunSource, item, `${path}.source`, contract, refStack);
          break;
        }
        case "started_at": {
          if (typeof item !== "string") fail(contract, `${path}.started_at`, "expected string");
          if (Number.isNaN(Date.parse(item as string))) fail(contract, `${path}.started_at`, "expected date-time string");
          break;
        }
        case "status": {
          if (item !== "RUNNING") fail(contract, `${path}.status`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.status`, "expected string");
          break;
        }
        case "target": {
          validateUnion(contract, `${path}.target`, [
            () => {
              validateReference("OperationTarget", validateOperationTarget, item, `${path}.target`, contract, refStack);
            },
            () => {
              if (item !== null) fail(contract, `${path}.target`, "expected null");
            },
          ]);
          break;
        }
        case "targets": {
          if (!Array.isArray(item)) fail(contract, `${path}.targets`, "expected array");
          (item as unknown[]).forEach((item, index) => {
            validateReference("RepositoryIdentity", validateRepositoryIdentity, item, `${`${path}.targets`}[${index}]`, contract, refStack);
          });
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
